                     s => s.StudentID == e.StudentID &&
                          s.CourseID == e.CourseID).SingleOrDefault();
                 if (enrollmentInDataBase == null)
                 {
                     context.Enrollments.Add(e);
                 }
             }
             context.SaveChanges();
         }
     }
 }

