using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to prevent cross-test contamination
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after each test as well
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesCorrectMessage()
        {
            // Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            // Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            // Act
            _sut.SendNotification("Student", "1", "Jane", EntityOperation.CREATE, "admin");
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("admin", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Act
            _sut.SendNotification("Student", "1", "Jane", EntityOperation.CREATE, null);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageStartsWithNew()
        {
            _sut.SendNotification("Department", "5", "Math", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            Assert.StartsWith("New ", notification.Message);
            Assert.Contains("has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_MessageContainsUpdated()
        {
            _sut.SendNotification("Department", "5", "Math", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            Assert.Contains("has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageContainsDeleted()
        {
            _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            Assert.Contains("has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            var before = DateTime.Now.AddSeconds(-1);
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now.AddSeconds(1);
            var notification = _sut.ReceiveNotification();

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_Dequeues_InFifoOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
        }

        [Fact]
        public void ReceiveNotification_AfterDequeue_QueueIsEmpty()
        {
            _sut.SendNotification("X", "1", EntityOperation.CREATE);
            _sut.ReceiveNotification();

            Assert.Null(_sut.ReceiveNotification());
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op but should not throw
            var ex = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(ex);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() => service.Dispose());
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Student", "7", "   ", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            Assert.Equal("Student (ID: 7) has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Student", "7", "", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            Assert.Equal("Student (ID: 7) has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_MultipleNotifications_AllQueued()
        {
            for (int i = 0; i < 5; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            var notifications = new List<Notification>();
            Notification n;
            while ((n = _sut.ReceiveNotification()) != null)
            {
                notifications.Add(n);
            }

            Assert.Equal(5, notifications.Count);
            for (int i = 0; i < 5; i++)
            {
                Assert.Equal(i.ToString(), notifications[i].EntityId);
            }
        }
    }
}

