using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
                new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") },
                new Student { FirstMidName = "Gytis", LastName = "Barzdukas", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { FirstMidName = "Yan", LastName = "Li", EnrollmentDate = DateTime.Parse("2012-09-01") }
            );
            _context.SaveChanges();
        }

        // --- Index Tests ---

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            SeedStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            Assert.True(model.Count > 0);
            // Default sort is OrderBy(LastName), so first should be "Alexander"
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            SeedStudents();

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            Assert.Equal("Li", model.First().LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            SeedStudents();

            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            // Earliest enrollment date is 2010-09-01 (Alexander)
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            SeedStudents();

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            // Latest enrollment date is 2013 (Anand)
            Assert.Equal("Anand", model.First().LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersResults()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Al", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            // "Alexander" and "Alonso" match "Al" in LastName
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_SearchString_FiltersOnFirstMidName()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Yan", null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Li", model.First().LastName);
        }

        [Fact]
        public void Index_NewSearch_ResetsPageToOne()
        {
            SeedStudents();

            // When searchString is not null, page should be reset to 1
            var result = _controller.Index(null, null, "Alex", 3) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            SeedStudents();

            var result = _controller.Index(null, "Li", null, null) as ViewResult;
            var model = result.Model as PaginatedList<Student>;

            Assert.NotNull(model);
            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParms()
        {
            SeedStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_WithSortOrderDate_SetsDateDescSortParm()
        {
            SeedStudents();

            _controller.Index("Date", null, null, null);

            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_SetsCurrentFilterViewBag()
        {
            SeedStudents();

            _controller.Index(null, null, "test", null);

            Assert.Equal("test", _controller.ViewBag.CurrentFilter);
        }

        // --- Details Tests ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var studentId = _context.Students.First().ID;

            var result = _controller.Details(studentId) as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(studentId, model.ID);
        }

        [Fact]
        public void Details_InvalidId_ThrowsInvalidOperationException()
        {
            // Details uses .Single() which throws when no match found
            Assert.Throws<InvalidOperationException>(() => _controller.Details(99999));
        }

        // --- Create GET Tests ---

        [Fact]
        public void Create_GET_ReturnsViewWithStudentDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // --- Create POST Tests ---

        [Fact]
        public void Create_POST_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2024-01-01")
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidStudent_SavesStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2024-01-01")
            };

            _controller.Create(student);

            Assert.Single(_context.Students);
            var saved = _context.Students.First();
            Assert.Equal("Test", saved.FirstMidName);
            Assert.Equal("Student", saved.LastName);
        }

        [Fact]
        public void Create_POST_MinValueDate_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_POST_OutOfRangeDate_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(1000, 1, 1) // Before 1753
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2024-01-01")
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.Same(student, result.Model);
        }

        // --- Edit GET Tests ---

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var student = _context.Students.First();

            var result = _controller.Edit(student.ID) as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
            Assert.Equal(student.LastName, model.LastName);
        }

        [Fact]
        public void Edit_GET_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(99999);

            Assert.IsType<NotFoundResult>(result);
        }

        // --- Edit POST Tests ---

        [Fact]
        public void Edit_POST_ValidStudent_RedirectsToIndex()
        {
            SeedStudents();
            var student = _context.Students.First();
            // Detach to avoid tracking conflict
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Updated",
                LastName = "Name",
                EnrollmentDate = DateTime.Parse("2024-06-01")
            };

            var result = _controller.Edit(updated);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_POST_MinValueDate_AddsModelError()
        {
            SeedStudents();
            var student = _context.Students.First();
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(updated) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Edit_POST_InvalidModelState_ReturnsView()
        {
            var student = new Student
            {
                ID = 1,
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2024-01-01")
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            var result = _controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET Tests ---

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var student = _context.Students.First();

            var result = _controller.Delete(student.ID) as ViewResult;

