            var english = context.Departments.FirstOrDefault(d => d.Name == "English");
            Assert.NotNull(english);
            Assert.Equal(350000, english.Budget);
            var admin = context.Instructors.Find(english.InstructorID);
            Assert.Equal("Abercrombie", admin.LastName);
        }
