        [Fact]
        public void SendNotification_ExceedingMaxQueueLength_OldestItemsRemoved()
        {
            // The max queue length is 500. Enqueue 510 items and verify cap enforcement.
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            var notifications = new List<Notification>();
            Notification n;
            while ((n = _sut.ReceiveNotification()) != null)
            {
                notifications.Add(n);
            }

            // Queue should be capped at 500 or less
            Assert.True(notifications.Count <= 500, $"Queue should be capped at 500 but had {notifications.Count}");
            Assert.True(notifications.Count > 0, "Queue should not be empty");
        }

        [Fact]
        public void SendNotification_FourArgOverload_DelegatesToFiveArgOverload()
        {
            // The 4-arg overload calls the 5-arg with null displayName
            _sut.SendNotification("Student", "10", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Equal("Student (ID: 10) has been deleted", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
        }
    }
}

