 using System;
 using ContosoUniversity.Controllers;
 using ContosoUniversity.Data;
 using ContosoUniversity.Models;
 using ContosoUniversity.Services;
 using ContosoUniversity.Tests.Helpers;
 using Microsoft.AspNetCore.Mvc;
 using Xunit;

 namespace ContosoUniversity.Tests.Controllers
 {
     public class NotificationsControllerTests : IDisposable
     {
         private readonly SchoolContext _context;
         private readonly NotificationsController _controller;
         private readonly NotificationService _notificationService;

         public NotificationsControllerTests()
         {
             _context = TestDbContextFactory.Create();
             _controller = new NotificationsController(_context);
             _notificationService = new NotificationService();
             // Drain the static queue before each test
             while (_notificationService.ReceiveNotification() != null) { }
         }

         public void Dispose()
         {
             // Drain after test
             while (_notificationService.ReceiveNotification() != null) { }
             _notificationService.Dispose();
             _controller.Dispose();
             _context.Dispose();
         }

         [Fact]
         public void GetNotifications_EmptyQueue_ReturnsEmptyNotifications()
         {
             var result = _controller.GetNotifications();

             Assert.IsType<JsonResult>(result);
             // The result value should have success=true and count=0
             dynamic data = result.Value;
             Assert.NotNull(data);
         }

         [Fact]
         public void GetNotifications_WithNotifications_ReturnsUpTo10()
         {
             // Enqueue 15 notifications via the static queue
             for (int i = 0; i < 15; i++)
             {
                 _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
             }

             var result = _controller.GetNotifications();

             Assert.IsType<JsonResult>(result);
             // Verify the anonymous object returned
             var value = result.Value;
             var successProp = value.GetType().GetProperty("success");
             var countProp = value.GetType().GetProperty("count");
             var notifProp = value.GetType().GetProperty("notifications");
             Assert.NotNull(successProp);
             Assert.True((bool)successProp.GetValue(value));
             Assert.Equal(10, (int)countProp.GetValue(value));
             var notifs = notifProp.GetValue(value) as System.Collections.Generic.List<Notification>;
             Assert.Equal(10, notifs.Count);
         }

         [Fact]
         public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
         {
             var result = _controller.GetNotifications();

             Assert.IsType<JsonResult>(result);
             var value = result.Value;
             var successProp = value.GetType().GetProperty("success");
             var countProp = value.GetType().GetProperty("count");
             Assert.True((bool)successProp.GetValue(value));
             Assert.Equal(0, (int)countProp.GetValue(value));
         }

         [Fact]
         public void GetNotifications_FewerThan10_ReturnsAll()
         {
             for (int i = 0; i < 3; i++)
             {
                 _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
             }

             var result = _controller.GetNotifications();

             var value = result.Value;
             var countProp = value.GetType().GetProperty("count");
             Assert.Equal(3, (int)countProp.GetValue(value));
         }

